// Standard-resource composition for a retained author upload/count view.
// Author scope is discovered through the standard manga authorOrArtist filter;
// it is never silently sent as an unsupported chapter parameter.
import type {PublicApiClient} from './client';
import type {Collection,Resource,Response} from './types';
import {publicQuery,canUseMangaFeed,chapterParentControls} from './query';
import {publicUuid,PublicApiContractError} from './validation';
const parentFilters=new Set([...chapterParentControls,'originalLanguage[]','excludedOriginalLanguage[]']);
const maxMangas=1000,maxChapters=10000;
const failed=(response:Response<unknown>)=>response.status<200||response.status>=300;
function compareValue(left:unknown,right:unknown):number{if(left===null||left===undefined)return right===null||right===undefined?0:1;if(right===null||right===undefined)return -1;if(typeof left==='number'&&typeof right==='number')return left-right;const a=String(left),b=String(right);if(/^\d+(?:\.\d+)?$/.test(a)&&/^\d+(?:\.\d+)?$/.test(b))return Number(a)-Number(b);return a<b?-1:a>b?1:0;}
export async function scopedMangaChapterCollection(api:PublicApiClient,input:URLSearchParams,signal?:AbortSignal):Promise<Response<Collection>>{
 const translated=publicQuery('chapterView',input,['manga','scanlation_group','user']),author=translated.get('authorOrArtist');if(author)publicUuid(author);if(![...translated.keys()].some(key=>chapterParentControls.has(key)))throw new PublicApiContractError('Parent chapter composition requires an explicit manga filter',422);
 const limit=Number(translated.get('limit')??100),offset=Number(translated.get('offset')??0),countOnly=limit===0,mangaQuery=new URLSearchParams({limit:'100',offset:'0'}),feedQuery=new URLSearchParams(),wantedMangas=new Set(translated.getAll('manga'));
 for(const[key,value]of translated){if(parentFilters.has(key)||key==='contentRating[]')mangaQuery.append(key,value);if(!parentFilters.has(key)&&!['limit','offset','manga'].includes(key)&&!key.startsWith('order['))feedQuery.append(key,value);}
 for(const id of wantedMangas)mangaQuery.append('ids[]',id);
 const mangas:string[]=[];let mangaTotal:number|undefined;for(let position=0;;position+=100){mangaQuery.set('offset',String(position));const response=await api.collection('/manga','manga',mangaQuery,signal);if(failed(response)||!response.body)return response;const body=response.body;if(mangaTotal===undefined)mangaTotal=body.total;else if(mangaTotal!==body.total)throw new PublicApiContractError('Scoped manga catalogue changed during pagination; reload the view',409);if(body.total>maxMangas)throw new PublicApiContractError('Scoped uploads exceed the bounded 1,000-title view budget',422);if(!body.data.length&&position<body.total)throw new PublicApiContractError('Scoped manga pagination stopped before its total');for(const row of body.data){const id=publicUuid(row.id);if(author&&!row.relationships.some(relation=>['author','artist'].includes(relation.type)&&publicUuid(relation.id)===author))throw new PublicApiContractError('Author filter returned a manga without that creator relationship');if(mangas.includes(id))throw new PublicApiContractError('Scoped manga pagination repeated an identity');if(!wantedMangas.size||wantedMangas.has(id))mangas.push(id);}if(position+body.data.length>=body.total)break;}
 let total=0;const rows:Resource[]=[],seen=new Set<string>();for(const mangaId of mangas){const useFeed=canUseMangaFeed(feedQuery),batchSize=useFeed?500:100;let expected:number|undefined;for(let position=0;;position+=batchSize){const query=new URLSearchParams(feedQuery);query.set('limit',countOnly?'1':String(batchSize));query.set('offset',String(position));if(!useFeed)query.set('manga',mangaId);const response=useFeed?await api.mangaFeed(mangaId,publicQuery('feed',query),signal):await api.collection('/chapter','chapter',publicQuery('chapter',query),signal);if(failed(response)||!response.body)return response;const body=response.body;if(expected===undefined){expected=body.total;total+=body.total;if(!Number.isSafeInteger(total))throw new PublicApiContractError('Scoped chapter total exceeds the safe integer budget');if(!countOnly&&total>maxChapters)throw new PublicApiContractError('Scoped uploads exceed the bounded 10,000-chapter view budget',422);}else if(expected!==body.total)throw new PublicApiContractError('Scoped chapter feed changed during pagination; reload the view',409);if(countOnly)break;if(!body.data.length&&position<body.total)throw new PublicApiContractError('Scoped chapter feed stopped before its total');for(const row of body.data){const parents=row.relationships.filter(relation=>relation.type==='manga');if(parents.length!==1||publicUuid(parents[0].id)!==mangaId||seen.has(publicUuid(row.id)))throw new PublicApiContractError('Scoped feed returned an ambiguous parent or duplicate chapter');seen.add(publicUuid(row.id));rows.push(row);}if(position+body.data.length>=body.total)break;}}
 if(!countOnly){if(rows.length!==total)throw new PublicApiContractError('Scoped uploads could not be fully materialized');const orders=[...translated].filter(([key])=>key.startsWith('order[')).map(([key,direction])=>({field:key.slice(6,-1),direction:direction==='asc'?1:-1}));if(!orders.length)orders.push({field:'publishAt',direction:-1});rows.sort((a,b)=>{for(const order of orders){const left=a.attributes[order.field],right=b.attributes[order.field];const numeric=order.field==='chapter'||order.field==='volume',key=(value:unknown)=>numeric?(typeof value==='string'&&/^\d+(?:\.\d+)?$/.test(value)?Number(value):null):value,aKey=key(left),bKey=key(right),comparison=compareValue(aKey,bKey);if(comparison)return aKey==null||bKey==null?comparison:order.direction*comparison;}return a.id<b.id?-1:a.id>b.id?1:0;});}
 return {status:200,body:{result:'ok',response:'collection',data:countOnly?[]:rows.slice(offset,offset+limit),limit,offset,total}};
}

export async function authorChapterCollection(api:PublicApiClient,input:URLSearchParams,signal?:AbortSignal){if(!input.has('authorOrArtist'))throw new PublicApiContractError('Author chapter composition requires one author UUID',422);return scopedMangaChapterCollection(api,input,signal);}
